import{_ as t,H as e,f as a,i as r}from"./chunks/framework.CBmkDW73.js";const l=JSON.parse('{"title":"最佳实践","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/best-practices.md","filePath":"zh/guide/best-practices.md"}'),n={name:"zh/guide/best-practices.md"};function s(c,o,d,i,p,h){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h1><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><p><strong>声明式写，不要叙述式。</strong> 用 <code>contract:</code>、<code>invariant:</code>、<code>test:</code>、<code>failure:</code> 这样的章节，不要编号步骤或散文。智能体读得快，跟随精确的声明。</p><p><strong>仅关闭影响实现的决策。</strong> 在移交 <code>plan</code> 前，解决：契约、数据形状、失败模式、测试标准。把哲学争论和&quot;锦上添花&quot;留在 <code>deferred</code> 或 <code>Working notes</code>。</p><p><strong>按路径引用代码，永不粘贴。</strong> 规范是关于要构建什么的决策，不是怎样构建的演走。</p><h2 id="计划" tabindex="-1">计划 <a class="header-anchor" href="#计划" aria-label="Permalink to &quot;计划&quot;">​</a></h2><p><strong>任务是 30-60 分钟各。</strong> 原子到智能体能推理它们。太大了你失去可见性；太小了开销杀死动量。</p><p><strong>Acceptance 可执行。</strong> 每个任务的验收条件必须是 CI/人类能验证的东西：测试名、命令或脚本。不模糊，不抱负。</p><p><strong>标记 <code>[parallel]</code> 仅当真正独立。</strong> 共享状态、错误处理或未闭合的契约 → 任务不并行。过度标记导致破坏的合并。</p><h2 id="git-工作流" tabindex="-1">Git 工作流 <a class="header-anchor" href="#git-工作流" aria-label="Permalink to &quot;Git 工作流&quot;">​</a></h2><p><strong>每个 RED-GREEN-refactor 循环一次提交。</strong> 把你的思考推进历史。后来调试时有帮助。</p><p><strong>每个循环后同步文档。</strong> 就在提交前。如果你等待，你会忘记你改了什么和为什么。</p><p><strong>用描述性分支名。</strong> <code>feat/oauth-github</code>，不是 <code>feature1</code>。当你有多个 worktree 时帮你导航。</p><h2 id="大型项目" tabindex="-1">大型项目 <a class="header-anchor" href="#大型项目" aria-label="Permalink to &quot;大型项目&quot;">​</a></h2><p><strong>当 ≥3 个里程碑时用 roadmap。</strong> 不要试着一次性计划他们。<code>plan</code> 仅当前的，随着你学习更新 stub。</p><p><strong>清晰标记当前里程碑。</strong> <code>← 现在详细计划</code> 在 M1 上信号意图。在计划 M2 前，ship 后移动标记。</p><p><strong>期望在 M1 后修改里程碑。</strong> 第一个里程碑教你剩下的会花费多少。那是要点。</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p><strong>隔离优先，假设其次。</strong> 缩小到最小重现。删除代码直到症状消失。仅然后问&quot;为什么&quot;。</p><p><strong>每次改一个变量。</strong> 并行假设很诱人但让很难知道哪个改变修复了它。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p><strong>测试契约，不是实现。</strong> 如果契约说&quot;成功时返回 200&quot;，测试那。不是&quot;调用 X 函数&quot;或&quot;从数据库 Y 读取&quot;。</p><p><strong>无内部的 mock。</strong> Mock 外部边界：HTTP、DB、文件系统。Mock 你自己的代码仅当真实版本很慢或非确定性。</p><h2 id="何时放弃" tabindex="-1">何时放弃 <a class="header-anchor" href="#何时放弃" aria-label="Permalink to &quot;何时放弃&quot;">​</a></h2><p><strong>如果假设实质改变，停止并重新探索。</strong> 不要强行通过如果你在解决的问题不再是问题了。用原因和学习标记尝试在探索笔记中。</p><p><strong>如果里程碑目标移位 ≥50%，回到设计。</strong> 不要扩展计划。承认新方向并重启。</p><h2 id="文档同步" tabindex="-1">文档同步 <a class="header-anchor" href="#文档同步" aria-label="Permalink to &quot;文档同步&quot;">​</a></h2><p><strong>Living docs 是事实，staging docs 是草稿。</strong> <code>ship</code> 后，规范移到 living docs。代码中的测试和注释与两者保持当前。</p><p><strong>README 是第一个规范。</strong> 如果它不匹配代码，PR 失败评审。同样规则适用于所有公共契约。</p>',29)])])}const u=t(n,[["render",s]]);export{l as __pageData,u as default};
